// TRUCHET CATHEDRAL
// Truchet tiles: each square holds two quarter-circle arcs (or a diagonal) and may sit either way round; laid side by side
// they close into rivers, rings and knots. Here the tiling is multi-scale (squares split into four, up to three times),
// and tiles turn by quarter-turns in waves that ripple outward, sweep across, fall in rows, or fire at random,
// so the pattern re-knots itself as the waves pass.
// Variables are re-read every frame; changing the grid or the scale mix rebuilds the tiling.

const SIZE = 800;

const PALETTES = {
  'cathedral glass':  { bg: '#0b0f24', ink: ['#2c5fd0', '#d63b4a', '#f1b93a', '#3aa57a', '#8d5bd0'] },
  'terrazzo':         { bg: '#efe7da', ink: ['#c0563a', '#2f6b6a', '#e0a84b', '#3a3a46', '#a8b8a0'] },
  'bauhaus primaries':{ bg: '#f2ede2', ink: ['#d6342c', '#1f4aa8', '#f2c230', '#161616', '#e8e0cf'] },
  'celadon and ink':  { bg: '#e6efe6', ink: ['#7fb5a0', '#2f6b5e', '#14252b', '#a9cdbd', '#4d8a7a'] },
  'sunset risograph': { bg: '#fbe9d5', ink: ['#f4506a', '#ff9a3c', '#6b3fa0', '#2a2d6b', '#ffc4a1'] },
  'moss and brick':   { bg: '#1d2118', ink: ['#7a9a4a', '#b5523a', '#d9c590', '#4d6a3a', '#8a3a2a'] },
  'monochrome ink':   { bg: '#f4f1ea', ink: ['#111111', '#333333', '#555555', '#777777', '#999999'] },
  'mint and coral':   { bg: '#12303a', ink: ['#7ee0c3', '#ff7a6b', '#ffd9a8', '#3aa6a0', '#f2f0e4'] },
  'cyanotype':        { bg: '#0b2a5b', ink: ['#e8f1ff', '#9cc2f2', '#5d94d8', '#c8dcf7', '#ffffff'] },
  'gilt on black':    { bg: '#08080a', ink: ['#e7c36b', '#b8893a', '#f6e3a6', '#8a6a2a', '#fff4cf'] }
};

const GRID = { 'six across': 6, 'eight across': 8, 'ten across': 10, 'fourteen across': 14, 'eighteen across': 18, 'twenty-four across': 24 };
const WEIGHT = { 'hairline': 0.012, 'fine': 0.03, 'medium': 0.07, 'bold': 0.12, 'heavy': 0.18, 'fat': 0.26 };

let tiles = [], builtKey = null;

function rng(seed) {                                   // small deterministic generator so a rebuilt tiling is stable
  return function () { seed |= 0; seed = (seed + 0x6D2B79F5) | 0; let t = Math.imul(seed ^ (seed >>> 15), 1 | seed); t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return ((t ^ (t >>> 14)) >>> 0) / 4294967296; };
}

function build(gridName, mix) {
  const G = GRID[gridName] || 10, s0 = SIZE / G, rand = rng(1234 + G * 7);
  p.noiseSeed(11);
  tiles = [];
  const maxLevel = G >= 18 ? 0 : (G >= 14 ? 1 : 2);
  function chance(x, y, level) {
    const d = Math.hypot(x - SIZE / 2, y - SIZE / 2) / (SIZE * 0.7);
    if (mix === 'one scale') return 0;
    if (mix === 'two scales') return level === 0 ? 0.35 : 0;
    if (mix === 'three scales') return 0.4;
    if (mix === 'small at the centre') return Math.max(0, 1.05 - d * 1.7) * (level === 0 ? 1 : 0.7);
    if (mix === 'large at the centre') return Math.max(0, d * 1.5 - 0.35) * (level === 0 ? 1 : 0.6);
    if (mix === 'a patchwork') return p.noise(x * 0.004, y * 0.004) > 0.5 ? 0.9 : 0.04;
    return 0;
  }
  function add(x, y, s, level) {
    if (level < maxLevel && rand() < chance(x + s / 2, y + s / 2, level)) {
      const h = s / 2;
      add(x, y, h, level + 1); add(x + h, y, h, level + 1); add(x, y + h, h, level + 1); add(x + h, y + h, h, level + 1);
    } else {
      tiles.push({ x: x + s / 2, y: y + s / 2, s: s, level: level, o: rand() < 0.5 ? 0 : 1, r: rand(), k: rand() });
    }
  }
  for (let j = 0; j < G; j++) for (let i = 0; i < G; i++) add(i * s0, j * s0, s0, 0);
}

function ease(x) { x = x < 0 ? 0 : x > 1 ? 1 : x; return x * x * (3 - 2 * x); }

// how far this tile has turned (in quarter-turns) at time t
function turn(tile, motion, t) {
  const cx = tile.x - SIZE / 2, cy = tile.y - SIZE / 2, d = Math.hypot(cx, cy);
  let u;
  if (motion === 'ripple from the centre') u = d * 0.011 - t * 0.55;
  else if (motion === 'a wind sweep') u = (tile.x + tile.y) * 0.0065 - t * 0.5;
  else if (motion === 'a travelling wave of rows') u = tile.y * 0.012 - t * 0.7;
  else if (motion === 'random flips') u = tile.r * 40 + t * (0.12 + tile.k * 0.25);
  else if (motion === 'breathing') return 0.18 * Math.sin(t * 0.9 + d * 0.012);
  else return 0;                                      // 'perfect stillness' and 'a slow turn of the whole lattice'
  const f = Math.floor(u);
  return f + ease((u - f - 0.4) / 0.2);          // a tile spends most of its time at rest, so the knots hold between waves
}

p.setup = function () {
  p.createCanvas(SIZE, SIZE);
  p.pixelDensity(1);
  p.frameRate(60);
};

p.draw = function () {
  const family = p.getSynthVar('family') || 'quarter arcs';
  const mix = p.getSynthVar('scale_mix') || 'two scales';
  const gridName = p.getSynthVar('grid') || 'ten across';
  const motion = p.getSynthVar('motion') || 'ripple from the centre';
  const palName = p.getSynthVar('palette') || 'cathedral glass';
  const logic = p.getSynthVar('colour_logic') || 'by distance from the centre';
  const lineName = p.getSynthVar('line') || 'medium';

  const key = gridName + '|' + mix;
  if (key !== builtKey) { build(gridName, mix); builtKey = key; }
  const pal = PALETTES[palName] || PALETTES['cathedral glass'];
  const wFac = WEIGHT[lineName] || 0.07;
  const t = p.frameCount / 60, ctx = p.drawingContext;

  ctx.setLineDash([]); ctx.lineCap = 'butt';
  ctx.fillStyle = pal.bg; ctx.fillRect(0, 0, SIZE, SIZE);
  ctx.save();
  if (motion === 'a slow turn of the whole lattice') {
    ctx.translate(SIZE / 2, SIZE / 2); ctx.rotate(Math.sin(t * 0.2) * 0.6 + t * 0.03); ctx.scale(1.5, 1.5); ctx.translate(-SIZE / 2, -SIZE / 2);
  }

  // work out colour and angle for every tile, then draw them grouped by (colour, level) so each group is one stroke
  const groups = {};
  for (let i = 0; i < tiles.length; i++) {
    const tile = tiles[i], cx = tile.x - SIZE / 2, cy = tile.y - SIZE / 2;
    const q = turn(tile, motion, t);
    const phi = (tile.o + q) * 1.5708;
    let ci;
    if (logic === 'by scale') ci = tile.level * 2 + (tile.r > 0.5 ? 1 : 0);
    else if (logic === 'by diagonal bands') ci = Math.floor((tile.x + tile.y) / 150 + t * 0.35);
    else if (logic === 'by orientation') ci = Math.floor(q + tile.o * 2 + 1) & 3;
    else if (logic === 'by noise cloud') ci = Math.floor(p.noise(tile.x * 0.004, tile.y * 0.004, t * 0.12) * 5);
    else if (logic === 'single ink') ci = 0;
    else ci = Math.floor(Math.hypot(cx, cy) / 85 - t * 0.3);                    // 'by distance from the centre'
    ci = ((ci % 5) + 5) % 5;
    const gk = ci * 4 + tile.level;
    (groups[gk] = groups[gk] || []).push(tile, phi);
  }

  for (const gk in groups) {
    const list = groups[gk], ci = Math.floor(gk / 4), color = pal.ink[ci];
    const s = list[0].s;                                                          // all tiles in a group share a level, so a size
    const passes = family === 'double arcs' ? [-0.22, 0.22] : family === 'triple arcs' ? [-0.3, 0, 0.3] : [0];
    const lw = s * wFac * (passes.length > 1 ? (passes.length === 3 ? 0.4 : 0.55) : 1);
    ctx.strokeStyle = color; ctx.lineWidth = Math.max(0.6, lw);
    if (family === 'dotted arcs') { ctx.lineCap = 'round'; ctx.lineWidth = Math.max(1, s * 0.07); ctx.setLineDash([0.1, s * 0.14]); } else { ctx.lineCap = 'butt'; ctx.setLineDash([]); }
    ctx.beginPath();
    for (let n = 0; n < list.length; n += 2) {
      const tile = list[n], phi = list[n + 1], h = tile.s / 2, c = Math.cos(phi), sn = Math.sin(phi);
      if (family === 'diagonals') {
        ctx.moveTo(tile.x + (-h * c + h * sn), tile.y + (-h * sn - h * c));
        ctx.lineTo(tile.x + (h * c - h * sn), tile.y + (h * sn + h * c));
      } else {
        for (let k = 0; k < passes.length; k++) {
          const r = h * (1 + passes[k]);
          // arc centred on the top-left corner, then the one on the bottom-right, both turned by phi
          const ax = tile.x + (-h * c + h * sn), ay = tile.y + (-h * sn - h * c);
          const bx = tile.x + (h * c - h * sn), by = tile.y + (h * sn + h * c);
          ctx.moveTo(ax + r * Math.cos(phi), ay + r * Math.sin(phi));
          ctx.arc(ax, ay, r, phi, phi + 1.5708);
          ctx.moveTo(bx + r * Math.cos(phi + 3.1416), by + r * Math.sin(phi + 3.1416));
          ctx.arc(bx, by, r, phi + 3.1416, phi + 4.7124);
        }
      }
    }
    ctx.stroke();
    if (family === 'fat tubes') {                                                  // a pale highlight down the middle of each tube
      ctx.strokeStyle = 'rgba(255,255,255,0.22)'; ctx.lineWidth = Math.max(0.6, lw * 0.28); ctx.stroke();
    }
  }
  ctx.restore();
  ctx.setLineDash([]); ctx.lineCap = 'butt';
  const vg = ctx.createRadialGradient(400, 400, 300, 400, 400, 600);
  vg.addColorStop(0, 'rgba(0,0,0,0)'); vg.addColorStop(1, 'rgba(0,0,0,0.28)');
  ctx.fillStyle = vg; ctx.fillRect(0, 0, SIZE, SIZE);
};
